$http.get('https://sts-dev.cancer.gov/v2/models/count',
  function (err, response, body) {

    if (err) {
        throw new Error(err);
    }

    console.log('Raw Body:', body);
    console.log('Status Code:', response.statusCode);

    assert.equal(response.statusCode, 200, 'Expected a 200 OK response');
    var count = Number(String(body).trim());
    assert.ok(!isNaN(count), 'Response should be a number');
    assert.ok(count > 0, 'Count should be greater than 0');
    console.log('Count:', count);

  }
);

