$http.post(
  'https://studycatalog-dev.cancer.gov/v1/graphql/',
  {
    json: {
      query: '{ numberOfPrograms }',
      variables: {}
    }
  },
  function (err, response, body) {
    if (err) {
      throw new Error(err);
    }

    console.log('Response:', body);
    console.log('Status:', response.statusCode);

    assert.equal(response.statusCode, 200, 'Expected a 200 OK response');
    assert.ok(
      !body.errors || body.errors.length === 0,
      'GraphQL errors: ' + JSON.stringify(body.errors)
    );

    var value = body.data && body.data.numberOfPrograms;

    assert.ok(
      Number.isFinite(value) && value !== 0,
      'Expected numberOfPrograms to be a non-zero number, got ' + value
    );
  }
);

